import asyncio

def parse(text):
    d={}
    for ln in text.splitlines():
        if "=" in ln:
            k,v=ln.split("=",1)
            d[k.strip()]=v.strip()
    return d

pr = await yuki_workspace_read({"path":"_walk_state.txt"})
visited=[]
next_path="nodes/60a6bb1c.txt"
sver=None
if pr.get("ok"):
    st=pr["data"]["text"]
    sver=pr["data"]["version"]
    for ln in st.splitlines():
        p=ln.split("\t")
        if p and p[0]=="NEXT":
            next_path=p[1]
        elif p and p[0]=="V":
            visited.append((p[1],p[2]))

while next_path not in ("END","DONE"):
    r=await yuki_workspace_read({"path":next_path})
    if not r.get("ok"):
        next_path="DONE"; break
    d=parse(r["data"]["text"])
    val=int(d["value"])
    visited.append((next_path,str(val)))
    idx=len(visited)-1
    ap="audit/%02d.txt"%idx
    chk=await yuki_workspace_read({"path":ap})
    if not chk.get("ok"):
        await yuki_workspace_write({"path":ap,"text":str(val)+"\n"})
    nxt=d["left"] if val%2==0 else d["right"]
    next_path=nxt
    st="NEXT\t"+next_path+"\n"+"".join("V\t%s\t%s\n"%(p,v) for p,v in visited)
    if sver:
        w=await yuki_workspace_write({"path":"_walk_state.txt","text":st,"expected_version":sver})
    else:
        w=await yuki_workspace_write({"path":"_walk_state.txt","text":st})
    sver=w["data"]["version"]

total=sum(int(v) for _,v in visited)
lines="".join("%s\t%s\n"%(p,v) for p,v in visited)+"TOTAL\t%d\n"%total
cr=await yuki_workspace_read({"path":"chain.tsv"})
if cr.get("ok"):
    await yuki_workspace_write({"path":"chain.tsv","text":lines,"expected_version":cr["data"]["version"]})
else:
    await yuki_workspace_write({"path":"chain.tsv","text":lines})
return {"visited":visited,"total":total}

